MultiLanguageSpellData['it'][22717] = {name = "Destriero da Guerra Nero", additional_info = "1.5 s di lancio\nFazione: Alleanza\n[q]Evoca e congeda un Destriero da Guerra Nero cavalcabile.\n[q]\"Questo destriero è stato addestrato a sopportare combattimenti brutali nel cuore dei più selvaggi campi di battaglia.\"\nMercante:\nTenente Karter\nZona:\nRoccavento\nCosto:\n15"}
MultiLanguageSpellData['it'][22718] = {name = "Kodo da Guerra Nero", additional_info = "1.5 s di lancio\nFazione: Orda\n[q]Evoca e congeda un Kodo da Guerra Nero cavalcabile.\n[q]\"Il Kodo da Guerra Nero viene allevato dagli Stallieri Kor'kron per il suo carattere aggressivo e imprevedibile. Il suo barrito di battaglia annuncia sempre uno spargimento di sangue.\"\nMercante:\nIncursore Bork\nZona:\nOrgrimmar\nCosto:\n15"}
MultiLanguageSpellData['it'][22719] = {name = "Calcaguerra Nero", additional_info = "1.5 s di lancio\nFazione: Alleanza\n[q]Evoca e congeda un Calcaguerra Nero cavalcabile.\n[q]\"Uno Gnomo in battaglia su una cavalcatura sufficientemente veloce è una vista terribile e spettacolare al tempo stesso.\" - Gran Meccanista Meccatork\nMercante:\nTenente Karter\nZona:\nRoccavento\nCosto:\n15"}
MultiLanguageSpellData['it'][22720] = {name = "Montone da Guerra Nero", additional_info = "1.5 s di lancio\nFazione: Alleanza\n[q]Evoca e congeda un Montone da Guerra Nero cavalcabile.\n[q]\"I Nani apprezzano i montoni per il coraggio con cui caricano in battaglia.\"\nMercante:\nTenente Karter\nZona:\nRoccavento\nCosto:\n15"}
MultiLanguageSpellData['it'][22721] = {name = "Raptor da Guerra Nero", additional_info = "1.5 s di lancio\nFazione: Orda\n[q]Evoca e congeda un Raptor da Guerra Nero cavalcabile.\n[q]\"Proviene dalla stessa stirpe di raptor a cui appartiene Ohgan, razza che ha portato spesso alla vittoria l'Impero dei Gurubashi.\"\nMercante:\nIncursore Bork\nZona:\nOrgrimmar\nCosto:\n15"}
MultiLanguageSpellData['it'][22722] = {name = "Cavallo da Guerra Scheletrico Rosso", additional_info = "1.5 s di lancio\nFazione: Orda\n[q]Evoca e congeda un Cavallo da Guerra Scheletrico Rosso cavalcabile.\n[q]\"Quando gli eroi caduti vengono fatti risorgere nella non morte, anche i loro destrieri subiscono lo stesso destino.\"\nMercante:\nIncursore Bork\nZona:\nOrgrimmar\nCosto:\n15"}
MultiLanguageSpellData['it'][22723] = {name = "Tigre da Guerra Nera", additional_info = "1.5 s di lancio\nFazione: Alleanza\n[q]Evoca e congeda una Tigre da Guerra Nera cavalcabile.\n[q]\"Così come le fiere della notte, le tigri sono rinomate per i loro taglienti artigli, la loro incredibile agilità e la passione per i grattini dietro alle orecchie.\"\nMercante:\nTenente Karter\nZona:\nRoccavento\nCosto:\n15"}
MultiLanguageSpellData['it'][22724] = {name = "Lupo da Guerra Nero", additional_info = "1.5 s di lancio\nFazione: Orda\n[q]Evoca e congeda un Lupo da Guerra Nero cavalcabile.\n[q]\"Animali particolarmente apprezzati dalle guardie di Orgrimmar per il loro ottimo senso dell'olfatto.\"\nMercante:\nIncursore Bork\nZona:\nOrgrimmar\nCosto:\n15"}
