MultiLanguageSpellData['it'][23077] = {name = "[q3]Riflettore Girogelido", additional_info = "3 s di lancio\nStrumenti:\nMartello da Fabbro , Chiave ad Arco\nReagenti:\nMeccanismo di Torio (6), Trasformatore di Verargento (2), Zaffiro Blu (2), Essenza di Fuoco (4), Olio del Freddo (2), Corolla Invernale (4)\nReagenti Facoltativi:\n[] (#50)\nMercante:\nXizzer Vitepazza\nZona:\nFontefredda\nCosto:\n1\n20\n\n[q3]Riflettore Girogelido\nSi vincola all'equipaggiamento\nMonile\n+3 Resistenza a Gelo\n[q2]Usa: Riflette gli incantesimi di gelo all'incantatore che li ha lanciati per 5 s. Probabilità di essere resistito se usato da personaggi di livello superiore a 49. (5 Min Recupero)\n20\nRichiedeIngegneria Classica\n(260)"}
MultiLanguageSpellData['it'][23078] = {name = "Defibrillatore dei Goblin XL", additional_info = "2 s di lancio\nReagenti:\nMeccanismo di Torio (2), Trasformatore di Verargento (2), Bobina di Fusione (2), Seta Ferrosa di Ragno (2), Rubino Stellato (2)\nBottino:\nSpiny Spazzanello\nZona:\nSotterranei di Roccianera\n\n[q2]Usa: Talvolta il defibrillatore può riportare in vita un alleato morto. Non utilizzabile in combattimento. (30 Min Recupero)\nRichiedeIngegneria Classica\n(265)"}
MultiLanguageSpellData['it'][23079] = {name = "[q2]Tecno-Ricostituente Maggiore", additional_info = "3 s di lancio\nReagenti:\nTubo di Torio (2), Trasformatore di Verargento , Tessuto di Telarunica (2)\nTesoro:\nTributo dei Gordok\nZona:\nMaglio Infausto\n\n[q2]Tecno-Ricostituente Maggiore\nMonile\n[q2]Usa: Rigenera 9 salute e mana su un bersaglio alleato e prova a dissolvere un effetto di metamorfosi. Risultati ridotti se l'effetto di metamorfosi è stato causato da incantatori di livello 0 o superiore. (5 Min Recupero)\n10 Carici\nRichiedeIngegneria Classica\n(275)"}
MultiLanguageSpellData['it'][23080] = {name = "Carica Potente di Nitronite", additional_info = "2 s di lancio\nReagenti:\nMeccanismo di Torio (2), Polvere Esplosiva Densa (3), Cuoio Duro (2), Acqua Sorgiva Rinfrescante\nMercante:\nXizzer Vitepazza\nZona:\nFontefredda\nCosto:\n1\n60\n\n[q2]Usa: Fa saltare porte e bauli resistenti chiusi.\nRichiedeIngegneria Classica\n(275)"}
