MultiLanguageSpellData['it'][24669] = {name = "Pioggia di Fuoco", additional_info = "250 mana Portata di 30 m\nCanalizzato (10 s di lancio)\n[q]Evoca una pioggia di fuoco e brucia tutti i nemici in un'area bersaglio, infliggendo 5 danni da fuoco ogni 2 s per 10 s."}
MultiLanguageSpellData['it'][24670] = {name = "Inferno", additional_info = "350 mana Portata di 100 m\n3 s di lancio\nReagenti:\nPietra Infernale\n[q]Evoca una meteora dalla Distorsione Fatua che infligge ([50% of Spell Power]) danni da fuoco e stordisce tutti i bersagli nemici nell'area bersaglio per 15 s. Un Infernale sorge dal cratere e serve l'incantatore per 1 min. Una volta perso il controllo, l'Infernale deve essere assoggettato per poterlo controllare nuovamente. Può essere usato solo all'esterno."}
