MultiLanguageSpellData['it'][53563] = {name = "Faro di Luce", additional_info = "{0.5% della base mana} {Portata di 60 m}\nIstantaneo\n[q]Avvolge un singolo alleato nell'energia sacra, così che le cure dirette fornite ad altri membri del gruppo o dell'incursione curino anche questo alleato del 20% delle cure fornite."}
