MultiLanguageSpellData['it'][57143] = {name = "Scarica di Vita", additional_info = "{50 energia} {Portata illimitata}\nIstantaneo\n[q]Rilascia una scarica d'energia rigenerante, curando i bersagli alleati entro 0 m e aumentando le cure fornite dall'incantatore del 5000%. L'entità e la durata delle cure aumentano in base ai punti combo:\n 1 punto: 5.000 cure/5 s\n 2 punti: 7.500 cure/10 s\n 3 punti: 10.000 cure/15 s\n 4 punti: 12.500 cure/20 s\n 5 punti: 15.000 cure/25 s"}
MultiLanguageSpellData['it'][57209] = {name = "Glifo - Geist", additional_info = "2 s di lancio\nStrumenti:\nCorredo da Runografo\nReagenti:\nCartapecora Leggera , Inchiostro del Leone (3)\nProfessione:\nRunografia (100)\nScoperta:\nRicerca: Inchiostro del Leone\n\nClassi: Cavaliere della Morte\n[q2]Usa: Apprendi in modo permanente questo glifo.\n\nRianima Cadavere evoca un Geist invece di un Ghoul.\n\n [ Sputafango : Disattivato se è stato scelto il talento Sputafango ] Esclusiva con: Glifo - Scheletro\n11"}
MultiLanguageSpellData['it'][57224] = {name = "Glifo - Legione dei Morti", additional_info = "2 s di lancio\nStrumenti:\nCorredo da Runografo\nReagenti:\nCartapecora Leggera , Inchiostro di Lunafulgida (3)\nProfessione:\nRunografia (25)\nScoperta:\nRicerca: Inchiostro di Lunafulgida\n\nClassi: Cavaliere della Morte\n[q2]Usa: Apprendi in modo permanente questo glifo.\n\nArmata dei Morti evoca una legione di servitori non morti casuali.\n11"}
MultiLanguageSpellData['it'][57263] = {name = "Glifo - Vilguardia", additional_info = "2 s di lancio 2\nStrumenti:\nCorredo da Runografo\nReagenti:\nCartapecora Leggera , Inchiostro Etereo (3)\nProfessione:\nRunografia delle Terre Esterne (1)\nScoperta:\nRicerca: Inchiostro Etereo\n\nClassi: Stregone\n[q2]Usa: Apprendi in modo permanente questo glifo.\n\nLa Vilguardia equipaggerà una spada, una mazza, un'ascia a due mani o un'arma ad asta casuale prendendola dal tuo zaino principale.\n11"}
