MultiLanguageSpellData['it'][61468] = {name = "Mirino Rifrangente Diamantato", additional_info = "[q0][Item Effect]3 s di lancio\nRichiede Arma a distanza\n[q]Applica in modo permanente un mirino a una balestra, a un arco o a un'arma da fuoco, aumentando i danni inflitti di 6.\n\n Applicare un mirino a un'arma la rende vincolata. Non applicabile a un oggetto di livello superiore a 320."}
