MultiLanguageSpellData['it'][63635] = {name = "Raptor Lanciascura", additional_info = "1.5 s di lancio\nFazione: Orda\n[q]Evoca e congeda un Raptor Lanciascura cavalcabile.\n[q]\"Questa razza di raptor, originariamente allevata dai Drakkari, viene ora comunemente usata anche dai Lanciascura a Nordania.\"\nMercante:\nSamamba\nZona:\nCorona di Ghiaccio\nCosto:\n100"}
MultiLanguageSpellData['it'][63636] = {name = "Montone di Forgiardente", additional_info = "1.5 s di lancio\nFazione: Alleanza\n[q]Evoca e congeda un Montone di Forgiardente cavalcabile.\n[q]\"Il Tassonomo dei Granmartello afferma che questa specifica razza di montone sia stata la prima addomesticata dai Nani quando fondarono Dun Morogh.\"\nMercante:\nDerrick Barbachiazza\nZona:\nCorona di Ghiaccio\nCosto:\n100"}
MultiLanguageSpellData['it'][63637] = {name = "Fiera della Notte Darnassiana", additional_info = "1.5 s di lancio\nFazione: Alleanza\n[q]Evoca e congeda una Fiera della Notte Darnassiana cavalcabile.\n[q]\"Quando muore una cavalcatura degli Elfi della Notte, il cavaliere tiene per tradizione una delle zanne della fiera per ricordare il compagno caduto.\"\nMercante:\nRook Pugnofalco\nZona:\nCorona di Ghiaccio\nCosto:\n100"}
MultiLanguageSpellData['it'][63638] = {name = "Tecnostruzzo di Gnomeregan", additional_info = "1.5 s di lancio\nFazione: Alleanza\n[q]Evoca e congeda un Tecnostruzzo di Gnomeregan cavalcabile.\n[q]\"Da usare quando devi arrivare a destinazione il prima possibile.\" - Rillie Girateste\nMercante:\nRillie Girateste\nZona:\nCorona di Ghiaccio\nCosto:\n100"}
MultiLanguageSpellData['it'][63639] = {name = "Elekk di Exodar", additional_info = "1.5 s di lancio\nFazione: Alleanza\n[q]Evoca e congeda un Elekk di Exodar cavalcabile.\n[q]\"L'Elekk di Exodar è una bestia consacrata da O'ros, il Naaru che ha viaggiato da Draenor verso Azeroth con Velen e i suoi seguaci.\"\nMercante:\nIrisee\nZona:\nCorona di Ghiaccio\nCosto:\n100"}
MultiLanguageSpellData['it'][63640] = {name = "Lupo di Orgrimmar", additional_info = "1.5 s di lancio\nFazione: Orda\n[q]Evoca e congeda un Lupo di Orgrimmar cavalcabile.\n[q]\"Per un certo periodo, gli Orchi usavano dire che erano \"affamati come un Lupo di Orgrimmar\". Qualche Elfo del Sangue usa ancora questa espressione in modo ironico.\"\nMercante:\nFreka Scurerossa\nZona:\nCorona di Ghiaccio\nCosto:\n100"}
MultiLanguageSpellData['it'][63641] = {name = "Kodo di Picco del Tuono", additional_info = "1.5 s di lancio\nFazione: Orda\n[q]Evoca e congeda un Kodo di Picco del Tuono cavalcabile.\n[q]\"Membro alfa del branco, questo kodo è un perfetto esemplare delle possenti creature che vivono a Mulgore.\"\nMercante:\nDoru Corno Tonante\nZona:\nCorona di Ghiaccio\nCosto:\n100"}
MultiLanguageSpellData['it'][63642] = {name = "Zampalesta di Lunargenta", additional_info = "1.5 s di lancio\nFazione: Orda\n[q]Evoca e congeda uno Zampalesta di Lunargenta cavalcabile.\n[q]\"Così ho detto che avevo voglia di mangiare pollo. Un secondo dopo ero a terra e quell'affare voleva scoprire che gusto avessero i miei occhi.\" - Bozzle Scoppiaviti\nMercante:\nTrellis Soldiurno\nZona:\nCorona di Ghiaccio\nCosto:\n100"}
MultiLanguageSpellData['it'][63643] = {name = "Cavallo da Guerra dei Reietti", additional_info = "1.5 s di lancio\nFazione: Orda\n[q]Evoca e congeda un Cavallo da Guerra dei Reietti cavalcabile.\n[q]\"Quando gli eroi caduti vengono fatti risorgere nella non morte, anche i loro destrieri subiscono lo stesso destino.\"\nMercante:\nEliza Killian\nZona:\nCorona di Ghiaccio\nCosto:\n100"}
