MultiLanguageSpellData['it'][65637] = {name = "Elekk Rosso Grande", additional_info = "1.5 s di lancio\nFazione: Alleanza\n[q]Evoca e congeda un Elekk Rosso Grande cavalcabile.\n[q]\"Mai comparsi su Nagrand, i primi cuccioli di elekk rossi sono nati su Azeroth dopo l'arrivo della Exodar. Alcuni ipotizzano che questa colorazione derivi dalle radiazioni provenienti dall'Isola Brumacremisi.\"\nMercante:\nIrisee\nZona:\nCorona di Ghiaccio\nCosto:\n500"}
MultiLanguageSpellData['it'][65638] = {name = "Fiera della Luna Rapida", additional_info = "1.5 s di lancio\nFazione: Alleanza\n[q]Evoca e congeda una Fiera della Luna Rapida cavalcabile.\n[q]\"Molti Elfi della Notte venerano queste orgogliose cavalcature poiché il loro manto luminoso simbolizza Elune, la Dea della Luna.\"\nMercante:\nRook Pugnofalco\nZona:\nCorona di Ghiaccio\nCosto:\n500"}
MultiLanguageSpellData['it'][65639] = {name = "Zampalesta Rosso Rapido", additional_info = "1.5 s di lancio\nFazione: Orda\n[q]Evoca e congeda uno Zampalesta Rosso Rapido cavalcabile.\n[q]\"Cosa vuol dire che è stato tinto? Oh, lo zampalesta. Effettivamente lo abbiamo leggermente ritoccato qua e là di rosso...\" - Trellis Soldiurno\nMercante:\nTrellis Soldiurno\nZona:\nCorona di Ghiaccio\nCosto:\n500"}
MultiLanguageSpellData['it'][65640] = {name = "Destriero Grigio Rapido", additional_info = "1.5 s di lancio\nFazione: Alleanza\n[q]Evoca e congeda un Destriero Grigio Rapido cavalcabile.\n[q]\"Veterano di alcune delle più violente battaglie combattute dalla Crociata d'Argento.\"\nMercante:\nCaporale Arthur Flew\nZona:\nCorona di Ghiaccio\nCosto:\n500"}
MultiLanguageSpellData['it'][65641] = {name = "Kodo Dorato Grande", additional_info = "1.5 s di lancio\nFazione: Orda\n[q]Evoca e congeda un Kodo Dorato Grande cavalcabile.\n[q]\"Membro alfa del branco, questo kodo è un perfetto esemplare delle possenti creature che vivono nelle Savane Meridionali.\"\nMercante:\nDoru Corno Tonante\nZona:\nCorona di Ghiaccio\nCosto:\n500"}
MultiLanguageSpellData['it'][65642] = {name = "Turbostruzzo", additional_info = "1.5 s di lancio\nFazione: Alleanza\n[q]Evoca e congeda un Turbostruzzo cavalcabile.\n[q]\"Lo specchietto non serve per guardare indietro, ma per permettere ai tuoi nemici di vedere qualcos'altro oltre ai tubi di scappamento.\" - Rillie Girateste\nMercante:\nRillie Girateste\nZona:\nCorona di Ghiaccio\nCosto:\n500"}
MultiLanguageSpellData['it'][65643] = {name = "Montone Violaceo Rapido", additional_info = "1.5 s di lancio\nFazione: Alleanza\n[q]Evoca e congeda un Montone Violaceo Rapido cavalcabile.\n[q]\"Le spesse ossa del cranio e le dure corna dei montoni di Barak Tor'ol rendono questa cavalcatura ideale per affrontare gruppi di nemici armati.\"\nMercante:\nDerrick Barbachiazza\nZona:\nCorona di Ghiaccio\nCosto:\n500"}
MultiLanguageSpellData['it'][65644] = {name = "Raptor Viola Rapido", additional_info = "1.5 s di lancio\nFazione: Orda\n[q]Evoca e congeda un Raptor Viola Rapido cavalcabile.\n[q]\"Storici alleati dei Troll, questi cacciatori delle giungle instaurano un profondo legame con i loro padroni. Diventano cavalcature, guardiani e compagni.\"\nMercante:\nSamamba\nZona:\nCorona di Ghiaccio\nCosto:\n500"}
MultiLanguageSpellData['it'][65645] = {name = "Cavallo da Guerra Scheletrico Bianco", additional_info = "1.5 s di lancio\nFazione: Orda\n[q]Evoca e congeda un Cavallo da Guerra Scheletrico Bianco cavalcabile.\n[q]\"Quando gli eroi caduti vengono fatti risorgere nella non morte, anche i loro destrieri subiscono lo stesso destino.\"\nMercante:\nEliza Killian\nZona:\nCorona di Ghiaccio\nCosto:\n500"}
MultiLanguageSpellData['it'][65646] = {name = "Lupo Bordeaux Rapido", additional_info = "1.5 s di lancio\nFazione: Orda\n[q]Evoca e congeda un Lupo Bordeaux Rapido cavalcabile.\n[q]\"I lupi dell'Orda non sono addomesticati, sono loro che scelgono di diventare dei compagni di vita.\"\nMercante:\nFreka Scurerossa\nZona:\nCorona di Ghiaccio\nCosto:\n500"}
