MultiLanguageSpellData['it'][84403] = {name = "Manciata di Viti d'Obsidio", additional_info = "1.5 s di lancio\nStrumenti:\nMartello da Fabbro\nReagenti:\nLingotto d'Obsidio (2)\nProfessione:\nIngegneria (1)Istruttore delle Professioni:\nIngegneria di Cataclysm (1)\nCosto:\n10\n\n(3)\nReagente d'artigianato"}
MultiLanguageSpellData['it'][84406] = {name = "Occhiali da Giovane Ingegnere Rampante", additional_info = "2 s di lancio\nStrumenti:\nMicroavvitatore Giromatico\nReagenti:\nLingotto d'Obsidio (8), Essonite (2), Cuoio Selvaggio (2)\nIstruttore delle Professioni:\nIngegneria di Cataclysm (1)\nCosto:\n10\n\nCosmetico\nSi vincola all'equipaggiamento\nTesta Decorativo\nIntegrità 40 / 40\n[q2]Equipaggia: Ti danno un aspetto competente che ispira grande fiducia tecnica.\n[q2]Usa: Aggiungi questo aspetto alla collezione della Brigata."}
MultiLanguageSpellData['it'][84408] = {name = "[q3]Mirino Professionale R19", additional_info = "2 s di lancio\nStrumenti:\nMartello da Fabbro , Microavvitatore Giromatico\nReagenti:\nLingotto d'Obsidio (6), Manciata di Viti d'Obsidio (6), Alicite (2)\nIstruttore delle Professioni:\nIngegneria di Cataclysm (1)\nCosto:\n10\n\n[q3]Mirino Professionale R19\n[q2]Usa: Applica in modo permanente un mirino a una balestra, a un arco o a un'arma da fuoco, aumentando l'indice di impatto a distanza di 17.\n\n Applicare un mirino a un'arma la rende vincolata. Non applicabile a un oggetto di livello superiore a 320.\n30"}
MultiLanguageSpellData['it'][84409] = {name = "Carica Esplosiva di Nitronite Volatile", additional_info = "2 s di lancio\nStrumenti:\nMicroavvitatore Giromatico\nReagenti:\nManciata di Viti d'Obsidio , Etere Elettrificato (2)\nIstruttore delle Professioni:\nIngegneria di Cataclysm (5)\nCosto:\n15\n\n[q2]Usa: Fa saltare porte e bauli chiusi che richiedono una competenza in Scasso di 35 o inferiore.\nRichiedeIngegneria di Cataclysm\n(1)"}
MultiLanguageSpellData['it'][84410] = {name = "[q3]Kit Rimozione Sistema di Sicurezza", additional_info = "2 s di lancio\nStrumenti:\nMicroavvitatore Giromatico\nReagenti:\nLingotto d'Obsidio (10), Manciata di Viti d'Obsidio (10)\nIstruttore delle Professioni:\nIngegneria di Cataclysm (1)\nCosto:\n10\n\n[q3]Kit Rimozione Sistema di Sicurezza\n[q2]Usa: Rimuove la sicura da un arco, una balestra o un'arma da fuoco, aumentando l'indice di celerità a distanza di 17.\n\n Usare il kit su un'arma la rende vincolata. Non applicabile a un oggetto di livello superiore a 320.\n30"}
MultiLanguageSpellData['it'][84411] = {name = "[q3]Arma da Fuoco ad Alto Potenziale", additional_info = "3 s di lancio\nStrumenti:\nMartello da Fabbro , Microavvitatore Giromatico\nReagenti:\nLingotto d'Obsidio (10), Manciata di Viti d'Obsidio (8), Etere Elettrificato (4)\nIstruttore delle Professioni:\nIngegneria di Cataclysm (15)\nCosto:\n50\n\n[q3]Arma da Fuoco ad Alto Potenziale\nSi vincola all'uso\n[q2]Usa: Spara diversi dardi esplosivi contro un bersaglio nemico per 108 danni e interrompe temporaneamente il lancio. Consuma una Manciata di Viti d'Obsidio ogni volta che vengono sparati. (2 Min Recupero)\n29\nRichiedeIngegneria di Cataclysm\n(1)\n[q]\"Tanto difficile da maneggiare quanto da costruire.\""}
MultiLanguageSpellData['it'][84412] = {name = "[q2]Distruttore di Mondi Personale", additional_info = "3.5 s di lancio\nStrumenti:\nArma da Fuoco ad Alto Potenziale , Martello da Fabbro\nReagenti:\nLingotto d'Obsidio (10), Manciata di Viti d'Obsidio (8), Etere Elettrificato (8)\nIstruttore delle Professioni:\nIngegneria di Cataclysm (25)\nCosto:\n1\n\n[q2]Distruttore di Mondi Personale\n[q2]Usa: Ti insegna a evocare questa mascotte.\n[q2]Clicca col pulsante destro per evocare e congedare un Distruttore di Mondi Personale.\nRichiede dal livello 1 al 80 ( 80)"}
